"use client"

import * as React from "react"
import { toast } from "sonner"

import { AppShell } from "@/components/app-shell"
import { MockupShell } from "@/components/mockup-shell"
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from "@/components/ui/alert-dialog"
import { Button } from "@/components/ui/button"
import { Card, CardContent } from "@/components/ui/card"
import { ToggleGroup, ToggleGroupItem } from "@/components/ui/toggle-group"
import {
  diffGrants,
  GRANTS,
  HIDDEN_NAV,
  ROLES,
  type PermissionId,
  type Role,
} from "@/lib/roles-permissions-data"
import { CreateRoleDialog } from "@/components/roles-permissions/create-role-dialog"
import { CreateRoleIcon } from "@/components/roles-permissions/icons"
import { RolesMatrix } from "@/components/roles-permissions/roles-matrix"
import { SaveChangesDialog } from "@/components/roles-permissions/save-changes-dialog"

/** Which chair the reviewer is sitting in. */
type Seat = "super-admin" | "org-admin"

/**
 * Roles and the permissions behind them — DES-170, from DIS-15 and the
 * Role-Based Access & Permissions PRD.
 *
 * Phase 1 has two halves. One is the split: `user` becomes call-only, `admin`
 * becomes a real org-level role, `superadmin` is unchanged — which this screen
 * both shows and edits. The other is that Sarj can make that change itself,
 * which is why the matrix is editable at all rather than a documentation page.
 *
 * The seat is a reviewer control rather than something to click into, because
 * you cannot become another role from inside the product — and the PRD's
 * fourth goal is about what the *other* seat sees. Flipping it changes the
 * sidebar as well as the page: an admin is handed eight superadmin destinations
 * today that bounce them straight back to the dashboard, and that gap is the
 * thing agent engineering actually ran into.
 */
export default function RolesPermissionsPage() {
  const [seat, setSeat] = React.useState<Seat>("super-admin")
  const [roles, setRoles] = React.useState<Role[]>(ROLES)
  const [grants, setGrants] =
    React.useState<Record<string, PermissionId[]>>(GRANTS)
  const [editingRoleId, setEditingRoleId] = React.useState<string | null>(null)
  const [draft, setDraft] = React.useState<PermissionId[]>([])
  const [creating, setCreating] = React.useState(false)
  const [confirming, setConfirming] = React.useState(false)
  const [discarding, setDiscarding] = React.useState(false)

  const canEdit = seat === "super-admin"
  const editing = roles.find((role) => role.id === editingRoleId)
  const diff = editing
    ? diffGrants(grants[editing.id] ?? [], draft)
    : { granted: [], revoked: [] }
  const changes = diff.granted.length + diff.revoked.length

  function startEdit(roleId: string) {
    setEditingRoleId(roleId)
    setDraft([...(grants[roleId] ?? [])])
  }

  function cancelEdit() {
    setEditingRoleId(null)
    setDraft([])
    setDiscarding(false)
  }

  /** Cancel throws work away, so it asks first once there is work to throw. */
  function requestCancel() {
    if (changes === 0) {
      cancelEdit()
      return
    }
    setDiscarding(true)
  }

  function toggle(permission: PermissionId, granted: boolean) {
    setDraft((current) =>
      granted
        ? [...current, permission]
        : current.filter((id) => id !== permission),
    )
  }

  function save() {
    if (!editing) return
    setGrants((current) => ({ ...current, [editing.id]: draft }))
    setConfirming(false)
    /* The footer bar disappearing is not confirmation that anything saved,
       and this is the one action on the page that reaches other people. */
    toast(`${editing.name} updated`, {
      description: `${editing.people} people in ${editing.organizations} organizations now have this access.`,
    })
    cancelEdit()
  }

  function createRole({
    name,
    permissions,
  }: {
    name: string
    permissions: PermissionId[]
  }) {
    const id = `role-${roles.length + 1}`
    setRoles((current) => [
      ...current,
      {
        id,
        name,
        legacy: null,
        people: 0,
        organizations: 0,
        locked: false,
      },
    ])
    setGrants((current) => ({ ...current, [id]: permissions }))
    setCreating(false)
    setEditingRoleId(id)
    setDraft(permissions)
  }

  return (
    <MockupShell
      actions={
        <>
          <span className="text-xs text-muted-foreground">Seat</span>
          <ToggleGroup
            onValueChange={(value) => {
              if (!value) return
              setSeat(value as Seat)
              cancelEdit()
            }}
            size="sm"
            type="single"
            value={seat}
            variant="outline"
          >
            <ToggleGroupItem value="super-admin">Super admin</ToggleGroupItem>
            <ToggleGroupItem value="org-admin">Org admin</ToggleGroupItem>
          </ToggleGroup>
        </>
      }
      eyebrow="Configuration"
      title="Design view-only role and permissions updates"
    >
      <AppShell
        active="Roles"
        hiddenItems={canEdit ? undefined : HIDDEN_NAV["org-admin"]}
      >
        <main className="flex flex-1 flex-col gap-6 p-3 lg:p-4">
          <header className="flex items-start justify-between gap-4">
            <div className="flex flex-col gap-1">
              <h1 className="text-2xl font-semibold">Roles</h1>
              <p className="text-sm text-muted-foreground">
                {canEdit
                  ? "What each role can do, everywhere on the platform."
                  : "What each role in your organization can do. Sarj defines these."}
              </p>
            </div>

            {canEdit ? (
              <Button onClick={() => setCreating(true)}>
                <CreateRoleIcon />
                Create role
              </Button>
            ) : null}
          </header>

          <RolesMatrix
            canEdit={canEdit}
            draft={draft}
            editingRoleId={editingRoleId}
            grants={grants}
            onStartEdit={startEdit}
            onToggle={toggle}
            roles={roles}
          />

          {/* Fixed, not sticky, and not a card footer. 39 rows put a footer two
              screens below the row you just ticked — a save button nobody
              finds. `sticky` is no help either: the shell's scroll container
              never actually scrolls, so there is nothing to stick to. Pinned to
              the corner it is in reach from any row, and clear of the sidebar. */}
          {editing ? (
            <Card className="fixed end-6 bottom-6 z-sticky" size="sm">
              <CardContent className="flex items-center gap-2">
                <div className="flex shrink-0 items-center gap-2">
                  <Button onClick={requestCancel} size="sm" variant="ghost">
                    Cancel
                  </Button>
                  <Button
                    disabled={changes === 0}
                    onClick={() => setConfirming(true)}
                    size="sm"
                  >
                    Review changes
                  </Button>
                </div>
              </CardContent>
            </Card>
          ) : null}
        </main>
      </AppShell>

      <CreateRoleDialog
        onCreate={createRole}
        onOpenChange={setCreating}
        open={creating}
      />

      <AlertDialog onOpenChange={setDiscarding} open={discarding}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>
              Discard {changes} {changes === 1 ? "change" : "changes"}?
            </AlertDialogTitle>
            <AlertDialogDescription>
              {editing?.name} goes back to what it could do before you started.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Keep editing</AlertDialogCancel>
            <AlertDialogAction onClick={cancelEdit}>Discard</AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>

      <SaveChangesDialog
        granted={diff.granted}
        onConfirm={save}
        onOpenChange={setConfirming}
        open={confirming}
        revoked={diff.revoked}
        role={editing}
      />
    </MockupShell>
  )
}

"use client"

import {
  ArrowDown01Icon,
  BlockGameIcon,
  BookOpen02Icon,
  BubbleChatIcon,
  Building02Icon,
  CallRinging04Icon,
  Chart03Icon,
  ChartColumnIcon,
  CodeIcon,
  DashboardBrowsingIcon,
  DashboardCircleIcon,
  Globe02Icon,
  GoogleDocIcon,
  Key01Icon,
  Message02Icon,
  PlayIcon,
  PlusSignIcon,
  Queue02Icon,
  RoboticIcon,
  Settings01Icon,
  ShieldKeyIcon,
  SmartPhone01Icon,
  CpuIcon,
  TaskDaily01Icon,
  TelephoneIcon,
  VariableIcon,
  VoiceIcon,
  WebhookIcon,
} from "@hugeicons/core-free-icons"

import { icon } from "@/components/icon"

/**
 * Icons for the shared product shell — one glyph per nav destination, matched
 * to the app's own sidebar. Icons *inside* a mockup live in that mockup's own
 * icons.tsx; this file is only the app chrome.
 */
export const PlaygroundIcon = icon(PlayIcon, "PlaygroundIcon")
export const PersonasIcon = icon(RoboticIcon, "PersonasIcon")
export const ScenariosIcon = icon(GoogleDocIcon, "ScenariosIcon")
export const KnowledgeIcon = icon(BookOpen02Icon, "KnowledgeIcon")
export const BatchCallsIcon = icon(Queue02Icon, "BatchCallsIcon")
export const TemplateIcon = icon(DashboardCircleIcon, "TemplateIcon")
export const GlobalPromptsIcon = icon(Globe02Icon, "GlobalPromptsIcon")
export const VoiceLibraryIcon = icon(VoiceIcon, "VoiceLibraryIcon")
export const DashboardIcon = icon(Chart03Icon, "DashboardIcon")
export const ConversationsIcon = icon(CallRinging04Icon, "ConversationsIcon")
export const MessagingIcon = icon(Message02Icon, "MessagingIcon")
export const QualityIcon = icon(DashboardBrowsingIcon, "QualityIcon")
export const ReportsIcon = icon(ChartColumnIcon, "ReportsIcon")
export const TasksIcon = icon(TaskDaily01Icon, "TasksIcon")
export const KeyIcon = icon(Key01Icon, "KeyIcon")
export const VariablesIcon = icon(VariableIcon, "VariablesIcon")
export const WebhooksIcon = icon(WebhookIcon, "WebhooksIcon")
export const IntegrationsIcon = icon(BlockGameIcon, "IntegrationsIcon")
export const DeveloperDocsIcon = icon(CodeIcon, "DeveloperDocsIcon")
export const BuildingIcon = icon(Building02Icon, "BuildingIcon")
export const RolesIcon = icon(ShieldKeyIcon, "RolesIcon")
export const MobileIcon = icon(SmartPhone01Icon, "MobileIcon")
/* The model catalog (DES-169), under Configuration. */
export const ModelsIcon = icon(CpuIcon, "ModelsIcon")
export const TelephonyIcon = icon(TelephoneIcon, "TelephonyIcon")
export const SettingsIcon = icon(Settings01Icon, "SettingsIcon")
export const MessagingSettingsIcon = icon(
  BubbleChatIcon,
  "MessagingSettingsIcon",
)
export const ChevronDownIcon = icon(ArrowDown01Icon, "ChevronDownIcon")
/** The hover "+" on Personas and Scenarios — creates one without leaving the nav. */
export const NewItemIcon = icon(PlusSignIcon, "NewItemIcon")

"use client"

import Image from "next/image"
import * as React from "react"

import { Avatar, AvatarFallback } from "@/components/ui/avatar"
import {
  Breadcrumb,
  BreadcrumbItem,
  BreadcrumbLink,
  BreadcrumbList,
  BreadcrumbPage,
  BreadcrumbSeparator,
} from "@/components/ui/breadcrumb"
import { Button } from "@/components/ui/button"
import {
  Collapsible,
  CollapsibleContent,
  CollapsibleTrigger,
} from "@/components/ui/collapsible"
import { Separator } from "@/components/ui/separator"
import {
  Sidebar,
  SidebarContent,
  SidebarGroup,
  SidebarGroupContent,
  SidebarGroupLabel,
  SidebarHeader,
  SidebarInset,
  SidebarMenu,
  SidebarMenuAction,
  SidebarMenuButton,
  SidebarMenuItem,
  SidebarProvider,
  SidebarTrigger,
  useSidebar,
} from "@/components/ui/sidebar"
import { cn } from "@/lib/utils"
import {
  BatchCallsIcon,
  BuildingIcon,
  ChevronDownIcon,
  ConversationsIcon,
  DashboardIcon,
  DeveloperDocsIcon,
  GlobalPromptsIcon,
  IntegrationsIcon,
  KeyIcon,
  KnowledgeIcon,
  MessagingIcon,
  MessagingSettingsIcon,
  MobileIcon,
  ModelsIcon,
  NewItemIcon,
  PersonasIcon,
  PlaygroundIcon,
  QualityIcon,
  ReportsIcon,
  RolesIcon,
  ScenariosIcon,
  SettingsIcon,
  TasksIcon,
  TelephonyIcon,
  TemplateIcon,
  VariablesIcon,
  VoiceLibraryIcon,
  WebhooksIcon,
} from "@/components/app-shell-icons"

/**
 * The app around any mockup screen, shared by every mockup that wants the
 * product chrome: an inset sidebar over a tinted page, and a header carrying
 * the breadcrumb and the account. Pass `active` to highlight the nav item the
 * screen lives under.
 *
 * Playground sits above the groups rather than inside one — it is the entry
 * point, not a build step. Configuration starts closed because it is the group
 * you visit once and then leave alone.
 */

interface NavItem {
  /** Label for the hover "+", on the two things you create most. */
  action?: string
  icon: React.ComponentType
  title: string
}

const PLAYGROUND: NavItem = { icon: PlaygroundIcon, title: "Playground" }

const NAV: { defaultOpen: boolean; items: NavItem[]; label: string }[] = [
  {
    defaultOpen: true,
    label: "Agents",
    items: [
      { action: "New persona", icon: PersonasIcon, title: "Personas" },
      { action: "New scenario", icon: ScenariosIcon, title: "Scenarios" },
      { icon: KnowledgeIcon, title: "Knowledge Bases" },
      { icon: BatchCallsIcon, title: "Batch Calls" },
      { icon: TemplateIcon, title: "Scenario Templates" },
      { icon: GlobalPromptsIcon, title: "Global Prompts" },
      { icon: VoiceLibraryIcon, title: "Voice Library" },
    ],
  },
  {
    defaultOpen: true,
    label: "Monitor",
    items: [
      { icon: DashboardIcon, title: "Dashboard" },
      { icon: ConversationsIcon, title: "Conversations" },
      { icon: MessagingIcon, title: "Messaging" },
      { icon: QualityIcon, title: "Quality Dashboard" },
      { icon: ReportsIcon, title: "Reports" },
      { icon: TasksIcon, title: "Tasks" },
    ],
  },
  {
    defaultOpen: false,
    label: "Configuration",
    items: [
      { icon: KeyIcon, title: "API Keys" },
      { icon: VariablesIcon, title: "Variables" },
      { icon: WebhooksIcon, title: "Webhooks" },
      { icon: IntegrationsIcon, title: "Integrations" },
      { icon: DeveloperDocsIcon, title: "Developer Docs" },
      { icon: BuildingIcon, title: "Organizations" },
      /* DES-170. Roles are platform-wide and Sarj-only in Phase 1, so they sit
         beside Organizations rather than inside one. */
      { icon: RolesIcon, title: "Roles" },
      { icon: MobileIcon, title: "Phone Numbers" },
      /* DES-169. The catalog needs a home in the nav, and Configuration is
         where the other platform-wide, Sarj-staff-only surfaces already sit. */
      { icon: ModelsIcon, title: "Models" },
      { icon: TelephonyIcon, title: "Telephony" },
      { icon: SettingsIcon, title: "Global Settings" },
      { icon: MessagingSettingsIcon, title: "Messaging Settings" },
    ],
  },
]

function NavLink({
  active,
  item,
  onNavigate,
}: {
  active: boolean
  item: NavItem
  onNavigate?: (title: string) => void
}) {
  return (
    <SidebarMenuItem>
      <SidebarMenuButton
        isActive={active}
        tooltip={item.title}
        onClick={() => onNavigate?.(item.title)}
      >
        <item.icon />
        <span className="truncate">{item.title}</span>
      </SidebarMenuButton>
      {/* `rounded-sm` in place of the primitive's `rounded-md` and `right-2` in
          place of `right-1`, both as the app has them.

          The glyph size is deliberately NOT the app's `[&>svg]:size-full`. That
          class works there because its plus is a hand-drawn 20×20 icon whose
          path spans only 6.5→13.5, so filling the box still draws a 7px plus.
          Ours is HugeIcons' PlusSignIcon, whose ink fills 16 of its 24 viewBox
          units — the same class drew a 12px plus, nearly twice the app's.
          `size-2.5` renders it at 10px, putting the drawn plus at 6.7px. */}
      {item.action ? (
        <SidebarMenuAction
          aria-label={item.action}
          className="top-1.5 right-2 rounded-sm border border-input bg-background text-muted-foreground hover:bg-accent hover:text-foreground [&>svg]:size-2.5"
        >
          <NewItemIcon />
        </SidebarMenuAction>
      ) : null}
    </SidebarMenuItem>
  )
}

/**
 * Collapsed to the icon rail there is no room for a section label, so the
 * groups are forced open and the label — the only thing that could close them —
 * is disabled.
 */
function NavGroup({
  active,
  defaultOpen,
  items,
  label,
  onNavigate,
}: {
  active: string
  defaultOpen: boolean
  items: NavItem[]
  label: string
  onNavigate?: (title: string) => void
}) {
  const { state } = useSidebar()
  const isCollapsed = state === "collapsed"
  const [open, setOpen] = React.useState(defaultOpen)

  return (
    <Collapsible
      disabled={isCollapsed}
      onOpenChange={isCollapsed ? undefined : setOpen}
      open={isCollapsed || open}
    >
      <SidebarGroup>
        <SidebarGroupLabel asChild>
          <CollapsibleTrigger className="flex w-full cursor-pointer items-center justify-between hover:bg-accent/50">
            <span>{label}</span>
            <ChevronDownIcon
              className={cn(
                "transition-transform duration-200 ease-out-cubic motion-reduce:transition-none",
                open ? "rotate-0" : "-rotate-90",
              )}
            />
          </CollapsibleTrigger>
        </SidebarGroupLabel>
        <CollapsibleContent>
          <SidebarGroupContent>
            <SidebarMenu>
              {items.map((item) => (
                <NavLink
                  active={item.title === active}
                  item={item}
                  key={item.title}
                  onNavigate={onNavigate}
                />
              ))}
            </SidebarMenu>
          </SidebarGroupContent>
        </CollapsibleContent>
      </SidebarGroup>
    </Collapsible>
  )
}

/** Breadcrumb start, account end — the row every page in the app sits under. */
function AppHeader({
  breadcrumb,
  showSettings,
}: {
  breadcrumb: string
  showSettings: boolean
}) {
  return (
    <header className="flex h-16 shrink-0 items-center justify-between gap-4 px-4">
      <Breadcrumb>
        <BreadcrumbList>
          <BreadcrumbItem>
            <BreadcrumbLink href="#">Home</BreadcrumbLink>
          </BreadcrumbItem>
          <BreadcrumbSeparator />
          <BreadcrumbItem>
            <BreadcrumbPage>{breadcrumb}</BreadcrumbPage>
          </BreadcrumbItem>
        </BreadcrumbList>
      </Breadcrumb>

      <div className="flex shrink-0 items-center gap-2">
        <Button size="sm" variant="outline">
          <DeveloperDocsIcon />
          Developer Doc
        </Button>
        {/* The same allowlist the nav reads. The app has this gear on its own
            check today, which is how an admin gets a second dead end to the
            page the sidebar already sent them to. */}
        {showSettings ? (
          <Button aria-label="Global settings" size="icon-sm" variant="outline">
            <SettingsIcon />
          </Button>
        ) : null}
        {/* Wrapped, rather than given `self-center`: the primitive ships
            `data-vertical:self-stretch`, and an attribute variant outranks a
            plain utility, so the rule stretched to the 28px row, got held to
            h-4, and settled at the top of it — 6px above the centre the buttons
            and the avatar share. Inside a wrapper of its own the flex line is
            the rule's own height, so stretching changes nothing and the wrapper
            is what the header centres. */}
        <div className="flex items-center">
          <Separator className="mx-1 h-4" orientation="vertical" />
        </div>
        {/* A rounded square at the same radius and height as the two buttons,
            not a circle. The app's account button is Clerk's, and Clerk does not
            inherit the app's CSS vars — so the real header sets its avatar
            radius to a 0.625rem literal, which is `--radius`, which is
            `rounded-lg`. A circle here is the one thing in this row that would
            not be in the app. `after:` and the fallback carry the primitive's
            own `rounded-full`, so both have to be squared off with it. */}
        <Avatar className="size-7 rounded-lg after:rounded-lg">
          <AvatarFallback className="rounded-lg">TA</AvatarFallback>
        </Avatar>
      </div>
    </header>
  )
}

export function AppShell({
  active,
  breadcrumb,
  hiddenItems,
  onNavigate,
  children,
}: {
  /** Title of the sidebar item this screen lives under, e.g. "Personas". */
  active: string
  /** Page label in the breadcrumb; defaults to `active`. */
  breadcrumb?: string
  /**
   * Nav item titles this viewer's role cannot open, so the menu holds only
   * what they can reach. Omit it and the nav is the full one, which is what
   * every other mockup wants.
   */
  hiddenItems?: readonly string[]
  /** Called with a nav item's title when it is clicked, so a mockup can make
   * the destinations it covers actually switch. Items it ignores stay inert. */
  onNavigate?: (title: string) => void
  children: React.ReactNode
}) {
  const hidden = new Set(hiddenItems ?? [])
  const groups = NAV.map((group) => ({
    ...group,
    items: group.items.filter((item) => !hidden.has(item.title)),
  })).filter((group) => group.items.length > 0)

  return (
    <SidebarProvider className="min-h-0 flex-1">
      {/* The sidebar pins to the viewport as it does in the app, so it clears
          the mockup shell's own header rather than sliding under it. */}
      <Sidebar className="pt-12" collapsible="icon" variant="inset">
        <SidebarHeader className="px-2 pt-2 pb-1">
          <div className="flex items-center justify-between group-data-[state=collapsed]:justify-center">
            {/* 56×32 is the size the app's own header renders it at. */}
            <Image
              alt="sarj.ai"
              className="group-data-[state=collapsed]:hidden"
              height={32}
              priority
              src="/logo.png"
              width={56}
            />
            <SidebarTrigger className="text-muted-foreground" />
          </div>
        </SidebarHeader>

        <SidebarContent>
          <SidebarGroup className="pt-2 pb-0">
            <SidebarGroupContent>
              <SidebarMenu>
                <NavLink
                  active={PLAYGROUND.title === active}
                  item={PLAYGROUND}
                  onNavigate={onNavigate}
                />
              </SidebarMenu>
            </SidebarGroupContent>
          </SidebarGroup>

          {groups.map((group, index) => (
            <React.Fragment key={group.label}>
              {/* The rail hides section labels, so a rule stands in for the
                  grouping those labels carry when the nav is open. */}
              {index > 0 ? (
                <div className="mx-2 my-1 hidden h-px shrink-0 bg-sidebar-border group-data-[collapsible=icon]:block" />
              ) : null}
              <NavGroup
                active={active}
                /* A closed group hiding the item the screen is on reads as the
                   nav having lost its place, so the active item's group opens
                   regardless of where the group would otherwise start. */
                defaultOpen={
                  group.defaultOpen ||
                  group.items.some((item) => item.title === active)
                }
                items={group.items}
                label={group.label}
                onNavigate={onNavigate}
              />
            </React.Fragment>
          ))}
        </SidebarContent>
      </Sidebar>

      <SidebarInset className="min-w-0 overflow-hidden">
        <AppHeader
          breadcrumb={breadcrumb ?? active}
          showSettings={!hidden.has("Global Settings")}
        />
        {/* No gutter here: the page owns its p-3 lg:p-4, matching the header. */}
        <div className="flex min-h-0 flex-1 flex-col overflow-auto">
          {children}
        </div>
      </SidebarInset>
    </SidebarProvider>
  )
}

"use client"

import { Button } from "@/components/ui/button"
import { Separator } from "@/components/ui/separator"
import {
  Tooltip,
  TooltipContent,
  TooltipTrigger,
} from "@/components/ui/tooltip"
import {
  setToolbar,
  useToolbarEnabled,
  useToolbarSuppressed,
} from "@/components/staff-toolbar"
import { CommentIcon } from "@/components/workspace-icons"

/**
 * Turns Vercel Comments on for the mockup under it.
 *
 * The toolbar is opt-in — mounting it for everyone prompts *every* visitor to
 * log in to Vercel — but the opt-in used to be a query param you had to know
 * about, so a link sent without it was a dead end. This is that same switch
 * with an address: last in the shell header, identical on every mockup.
 *
 * It stays visible once the toolbar is up. The header is reviewer chrome
 * rather than part of the design being reviewed, and leaving it there is what
 * makes turning commenting back off something other than a typed URL.
 */
export function CommentToggle() {
  const enabled = useToolbarEnabled()
  const suppressed = useToolbarSuppressed()

  if (suppressed) return null

  /* The divider belongs to the toggle rather than to the header, so that
     hiding one for a screenshot cannot leave the other stranded. */
  return (
    <>
      <Separator
        orientation="vertical"
        className="h-5 data-vertical:self-center"
      />

      <Tooltip>
        <TooltipTrigger asChild>
          <Button
            aria-label={
              enabled ? "Turn commenting off" : "Comment on this mockup"
            }
            aria-pressed={enabled}
            className={enabled ? undefined : "text-muted-foreground"}
            onClick={() => setToolbar(!enabled)}
